//! Support items for code generated by `#[ferritron::plugin]`. Not public API.

use crate::PluginInfo;
pub use crate::i18n::Localized;
pub use crate::parallel::set_audio_workgroup;
pub use crate::ui::UiTimer;

/// Connects a plugin type to its generated metadata.
pub trait PluginMeta {
    const INFO: &'static PluginInfo;
    /// Host-visible strings in the user's language, resolved once per process.
    fn localized() -> &'static Localized;
    /// `parallel = true` in the project file: start Ferritron's worker pool.
    const PARALLEL: bool = false;
    /// `[process] automation`: 0 control period (default), 1 every change, 2 events.
    const AUTOMATION: u8 = 0;
    /// `[process] control_block`: the control period in samples.
    const CONTROL_BLOCK: u32 = 32;
    /// `[mcp]` in the project file: the plugin gets an "AI Access" switch.
    const MCP: bool = false;
    /// `[quality]` in the project file: the plugin gets a "Quality" switch.
    const QUALITY: bool = false;
    /// `[ara]` in the project file: the plugin's ARA 2 support.
    fn ara() -> Option<&'static crate::abi::AraApi> {
        None
    }
    /// `[view] process = true`: the editor runs in a separate process.
    const VIEW_PROCESS: bool = false;
    /// The plugin's editor, if `[view]` is declared in the project file.
    fn view() -> Option<&'static crate::abi::ViewApi> {
        None
    }
    /// `[presets.<id>]` in the project file: the factory presets.
    fn presets() -> &'static [crate::presets::Preset] {
        &[]
    }
    /// The built-in "Program" parameter (generated with `[presets]`): an enum of the preset names.
    fn program_param() -> Option<&'static crate::ParamInfo> {
        None
    }
    /// `#[ferritron::plugin(worker = W)]`: builds the instance's worker.
    fn make_worker(params: &std::sync::Arc<dyn std::any::Any + Send + Sync>, instance: &crate::InstanceHandle) -> Option<Box<dyn crate::worker::WorkerObj>> {
        let _ = (params, instance);
        None
    }
    /// An instance was created (`true`) or destroyed (`false`): the editor
    /// backend may get ready ahead of time (`[view] preload`).
    fn preload_view(created: bool) {
        let _ = created;
    }
}

const fn fnv1a64(bytes: &[u8], seed: u64) -> u64 {
    let mut hash = 0xcbf2_9ce4_8422_2325 ^ seed;
    let mut i = 0;
    while i < bytes.len() {
        hash ^= bytes[i] as u64;
        hash = hash.wrapping_mul(0x0000_0100_0000_01b3);
        i += 1;
    }
    hash
}

/// Stable parameter ID from its key. Kept below 2^31 because some hosts
/// mishandle IDs that are negative as signed integers.
pub const fn param_id(key: &str) -> u32 {
    let hash = fnv1a64(key.as_bytes(), 0);
    ((hash ^ (hash >> 32)) as u32) & 0x7fff_ffff
}

/// ID of the built-in bypass parameter.
pub const BYPASS_ID: u32 = reserved_id("ferritron.bypass");
/// The built-in "Program" parameter of plugins with `[presets]`.
pub const PROGRAM_ID: u32 = reserved_id("ferritron.program");

/// Parameter IDs Ferritron keeps for itself (`0x4000_0000` and up).
pub const fn reserved_id(key: &str) -> u32 {
    ferritron_manifest::reserved_id(key)
}

/// First reserved parameter ID.
pub const RESERVED_BASE: u32 = ferritron_manifest::RESERVED_BASE;

/// Stable 16-byte class ID from the plugin ID.
pub const fn class_id(plugin_id: &str) -> [u8; 16] {
    let hi = fnv1a64(plugin_id.as_bytes(), 0x6665_7272_6974_726f).to_be_bytes();
    let lo = fnv1a64(plugin_id.as_bytes(), 0x6e00_0000_0000_0001).to_be_bytes();
    let mut out = [0u8; 16];
    let mut i = 0;
    while i < 8 {
        out[i] = hi[i];
        out[i + 8] = lo[i];
        i += 1;
    }
    out
}

/// Fails compilation when two parameter keys hash to the same ID.
pub const fn assert_unique_ids(ids: &[u32]) {
    let mut i = 0;
    while i < ids.len() {
        let mut j = i + 1;
        while j < ids.len() {
            assert!(ids[i] != ids[j], "two parameter keys produce the same ID; rename one of them");
            j += 1;
        }
        i += 1;
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn ids_are_stable() {
        // These values are stored in users' projects and must never change.
        assert_eq!(param_id("gain"), param_id("gain"));
        assert_ne!(param_id("gain"), param_id("mix"));
        assert!(param_id("gain") < 0x8000_0000);
        assert_ne!(class_id("com.example.a"), class_id("com.example.b"));
        // Packaging computes ids from the project file (LV2 ports, WAM keys): same function.
        for key in ["gain", "ferritron.bypass", "ferritron.quality", "ferritron.mcp", "some_long_parameter_key_42"] {
            assert_eq!(param_id(key), ferritron_manifest::param_id(key), "{key}");
        }
    }
}
